export function bundle(files){const g=p=>files.get(p)?.content||"";let html=g("/index.html")||"<h1>No index.html</h1>";const css=[...files.values()].filter(f=>f.path.endsWith(".css")).map(f=>`<style>${f.content}</style>`).join("\n");const js=[...files.values()].filter(f=>f.path.endsWith(".js")).map(f=>`<script>${f.content}</script>`).join("\n");if(html.includes("</head>"))html=html.replace("</head>",css+"</head>");else html=css+html;return html.replace("</body>",js+"</body>")}